def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 600.0  # OPT_PARAM: {"initial": 600.0, "min": 600, "max": 850, "type": "float"}
    pipeline_weight = 0.9  # OPT_PARAM: {"initial": 0.9, "min": 0.4, "max": 0.9, "type": "float"}
    responsiveness = 0.2  # OPT_PARAM: {"initial": 0.2, "min": 0.2, "max": 0.8, "type": "float"}

    smoothed_pipeline = sum(p * (responsiveness ** (i+1)) for i, p in enumerate(reversed(pipeline_orders)))
    net_position = on_hand_inventory + pipeline_weight * smoothed_pipeline
    order_amount = max(0, base_stock - net_position) * responsiveness
    return order_amount
